#include <iostream>
#include <deque>
using namespace std;

const int MAXN = 200005;
int a[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;
    for (int i = 0; i < n; i++) cin >> a[i];

    deque<int> dq;   // 存下标，值单调递减
    bool first = true;
    for (int i = 0; i < n; i++) {
        while (!dq.empty() && dq.front() <= i - k) dq.pop_front();  // 滑出窗口
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();  // 更小的没用
        dq.push_back(i);
        if (i >= k - 1) {
            if (!first) cout << ' ';
            cout << a[dq.front()];
            first = false;
        }
    }
    cout << "\n";
    return 0;
}
